    {
      "poi_id": "p10",
      "kind": "activity",
      "must_do_id": null,
      "note": "A new stop to stretch the legs and catch the everyday rhythm of Roma Norte, camera in hand.",
      "start": "11:00"
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
