{
  "title": "A slower day around the old centre",
  "summary": "A gentler day of history and local flavour, keeping Templo Mayor and swapping the rest for nearby gems.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": "m2",
